#include "battery_monitor.h"
static BatteryConfig_t cfg; static BatteryData_t data; static float previous_voltage_v; static uint8_t initialized;
static float clampf(float v,float lo,float hi){if(v<lo)return lo;if(v>hi)return hi;return v;}
static float estimate_soc(float v){float r=cfg.full_voltage_v-cfg.empty_voltage_v;if(r<=0.0f)return 0.0f;return clampf(((v-cfg.empty_voltage_v)/r)*100.0f,0.0f,100.0f);}
void Battery_Init(const BatteryConfig_t *config){if(!config)return;cfg=*config;data=(BatteryData_t){0};data.remaining_capacity_ah=cfg.capacity_ah;previous_voltage_v=cfg.full_voltage_v;initialized=1U;}
void Battery_Update(float voltage_v,float current_a,float temperature_c,float dt_seconds){if(!initialized)return;data.voltage_v=voltage_v;data.current_a=current_a;data.temperature_c=temperature_c;data.soc_percent=estimate_soc(voltage_v);if(dt_seconds>0.0f)data.voltage_trend_v_per_min=((voltage_v-previous_voltage_v)/dt_seconds)*60.0f;data.remaining_capacity_ah-=((current_a*dt_seconds)/3600.0f);data.remaining_capacity_ah=clampf(data.remaining_capacity_ah,0.0f,cfg.capacity_ah);previous_voltage_v=voltage_v;if(temperature_c>=cfg.max_temperature_c)data.status=BATTERY_STATUS_OVERTEMP;else if(current_a>=cfg.max_current_a)data.status=BATTERY_STATUS_OVERCURRENT;else if(voltage_v>(cfg.full_voltage_v+0.10f))data.status=BATTERY_STATUS_OVERVOLTAGE;else if(data.soc_percent<=cfg.low_soc_percent||voltage_v<=cfg.empty_voltage_v)data.status=BATTERY_STATUS_LOW;else data.status=BATTERY_STATUS_OK;}
BatteryData_t Battery_GetData(void){return data;}
const char *Battery_StatusString(BatteryStatus_t status){switch(status){case BATTERY_STATUS_OK:return "OK";case BATTERY_STATUS_LOW:return "LOW";case BATTERY_STATUS_OVERVOLTAGE:return "OVERVOLTAGE";case BATTERY_STATUS_OVERTEMP:return "OVERTEMP";case BATTERY_STATUS_OVERCURRENT:return "OVERCURRENT";default:return "UNKNOWN";}}
